export function digits(x){ // x>=0 finite -> {int:string, frac:string} exact expansion of shortest repr
  let s = x.toString();
  let exp = 0;
  const ei = s.indexOf('e');
  if (ei >= 0){ exp = parseInt(s.slice(ei+1),10); s = s.slice(0,ei); }
  const di = s.indexOf('.');
  if (di >= 0){ const fracLen = s.length - di - 1; s = s.slice(0,di)+s.slice(di+1); exp -= fracLen; }
  // s is a digit string, value = s * 10^exp
  s = s.replace(/^0+(?=\d)/,'');
  let intPart, fracPart;
  if (exp >= 0){ intPart = s + '0'.repeat(exp); fracPart = ''; }
  else { const k = -exp;
    if (s.length > k){ intPart = s.slice(0, s.length-k); fracPart = s.slice(s.length-k); }
    else { intPart = '0'; fracPart = '0'.repeat(k - s.length) + s; } }
  if (intPart === '') intPart='0';
  return {intPart, fracPart};
}
function inc(d){ let a=d.split(''); let i=a.length-1;
  while(i>=0){ if(a[i]==='9'){a[i]='0';i--;} else {a[i]=String(+a[i]+1); return a.join('');} }
  return '1'+a.join(''); }
export function quantize(intPart, fracPart, dp){
  let f = fracPart + '0'.repeat(Math.max(0, dp - fracPart.length));
  const keep = f.slice(0,dp); const rest = f.slice(dp);
  let coeff = (intPart === '0' ? '' : intPart) + keep;
  if (coeff === '') coeff = '0';
  let roundUp = false;
  if (rest.length){
    const first = rest[0];
    const restNonZero = /[1-9]/.test(rest.slice(1));
    if (first > '5') roundUp = true;
    else if (first === '5'){ if (restNonZero) roundUp = true;
      else { const last = coeff[coeff.length-1]; roundUp = (+last % 2) === 1; } }
  }
  if (roundUp) coeff = inc(coeff);
  coeff = coeff.replace(/^0+(?=\d)/,'');
  return coeff; // scaled integer string (no sign)
}
export function fmt(x, dp=2, sym='$'){
  const neg = (x<0) || Object.is(x,-0);
  const a = Math.abs(x);
  const {intPart, fracPart} = digits(a);
  let coeff = quantize(intPart, fracPart, dp);
  if (coeff.length > 28) throw new Error('InvalidOperation');
  coeff = coeff.padStart(dp+1,'0');
  let ip = dp? coeff.slice(0,coeff.length-dp) : coeff;
  const fp = dp? coeff.slice(coeff.length-dp) : '';
  let g=''; for(let i=0;i<ip.length;i++){ if(i>0 && (ip.length-i)%3===0) g+=','; g+=ip[i]; }
  return (neg?'-':'')+sym+g+(dp?'.'+fp:'');
}
